  fn test_put_operator_interface_operator_interface_desired_temp(value: *mut Isolette_Data_Model::Set_Points);
  fn test_get_thermostat_thermostat_heat_control(value: *mut Isolette_Data_Model::On_Off) -> bool;
  fn test_put_thermostat_thermostat_heat_control(value: *mut Isolette_Data_Model::On_Off);
  fn test_get_thermostat_thermostat_sv_currentSetPoints(value: *mut Isolette_Data_Model::Set_Points) -> bool;
  fn test_get_thermostat_thermostat_sv_lastCmd(value: *mut Isolette_Data_Model::On_Off) -> bool;
  fn test_get_heat_source_heat_source_sv_heater_state(value: *mut Isolette_Data_Model::On_Off) -> bool;
  fn test_put_thermostat_thermostat_sv_currentSetPoints(value: *mut Isolette_Data_Model::Set_Points);
