  fn test_put_heat_source_heat_source_sv_heater_state(value: *mut Isolette_Data_Model::On_Off);
  fn test_sent_temp_sensor_temp_sensor_temp_changed() -> u64;
  fn test_clear_thermostat_thermostat_temp_changed(cutoff: u64);
  fn test_sent_operator_interface_operator_interface_desired_temp() -> u64;
