/// Publish `value` to the port `temp_sensor_temp_sensor_temp_changed`, as its producer would.  Every consumer
/// receives it, and it ends this connection's setup batch (D39).
pub fn put_temp_sensor_temp_sensor_temp_changed(value: u8) {
  end_setup_batch_temp_sensor_temp_sensor_temp_changed();
  inject_temp_sensor_temp_sensor_temp_changed(value);
}

/// The send itself, without ending the setup batch: what the setters use.
fn inject_temp_sensor_temp_sensor_temp_changed(value: u8) {
  let mut v = value;
  unsafe { test_put_temp_sensor_temp_sensor_temp_changed(&mut v); }
  crate::system_tests::observe::injected_port_temp_sensor_temp_sensor_temp_changed(&v);
}

