/// Discard every event pending for `thermostat_thermostat` on its input `temp_changed`.  The thread applies
/// it at the start of its next dispatch, before reading any port; the other consumers
/// of the same connection keep what is pending for them (D39).
pub fn clear_thermostat_thermostat_temp_changed() {
  unsafe { test_clear_thermostat_thermostat_temp_changed(test_sent_temp_sensor_temp_sensor_temp_changed()); }
}

/// `None` for `thermostat_thermostat`'s input `temp_changed` in a setup container: nothing pending for it,
/// not even what a later setter in this batch injects.
fn setup_none_thermostat_thermostat_temp_changed() {
  unsafe {
    SETUP_NONE_thermostat_thermostat_temp_changed = true;
    test_clear_thermostat_thermostat_temp_changed(test_sent_temp_sensor_temp_sensor_temp_changed());
  }
}

/// `Some(value)` for `thermostat_thermostat`'s input `temp_changed`: exactly `value` pending for it.  The
/// first `Some` on the connection in a batch injects it once; another consumer's
/// `Some` with the same value shares that injection, and a different one fails the test.
fn setup_some_thermostat_thermostat_temp_changed(value: u8) {
  unsafe {
    SETUP_NONE_thermostat_thermostat_temp_changed = false;
    match &SETUP_BATCH_temp_sensor_temp_sensor_temp_changed {
      Some((s0, v, by)) => {
        if *v != value {
          crate::system_tests::harness::fail_with(format_args!(
            "setup conflict on {}: {} set {:?} and thermostat_thermostat.temp_changed set {:?}; the consumers of one connection receive the same events",
            "temp_sensor_temp_sensor_temp_changed", by, v, value));
          return;
        }
        test_clear_thermostat_thermostat_temp_changed(*s0);
      }
      None => {
        let s0 = test_sent_temp_sensor_temp_sensor_temp_changed();
        inject_temp_sensor_temp_sensor_temp_changed(value.clone());
        SETUP_BATCH_temp_sensor_temp_sensor_temp_changed = Some((s0, value, "thermostat_thermostat.temp_changed"));
        test_clear_thermostat_thermostat_temp_changed(s0);
        setup_resend_none_temp_sensor_temp_sensor_temp_changed();
      }
    }
  }
}

/// The setup batch on `temp_sensor_temp_sensor_temp_changed` (D39): the position before its injection, the value injected,
/// and which consumer's setup injected it.  None outside a batch.
static mut SETUP_BATCH_temp_sensor_temp_sensor_temp_changed: Option<(u64, u8, &'static str)> = None;
static mut SETUP_NONE_thermostat_thermostat_temp_changed: bool = false;

/// After the batch injects, a consumer already set to `None` must not receive it either.
fn setup_resend_none_temp_sensor_temp_sensor_temp_changed() {
  unsafe {
    let sent = test_sent_temp_sensor_temp_sensor_temp_changed();
    if SETUP_NONE_thermostat_thermostat_temp_changed { test_clear_thermostat_thermostat_temp_changed(sent); }
  }
}

fn end_setup_batch_temp_sensor_temp_sensor_temp_changed() {
  unsafe {
    SETUP_BATCH_temp_sensor_temp_sensor_temp_changed = None;
    SETUP_NONE_thermostat_thermostat_temp_changed = false;
  }
}

