/// End every connection's setup batch: at every scheduler command and at each test's
/// start.  What was already requested of the consumers stays requested.
pub(crate) fn end_setup_batches() {
  end_setup_batch_temp_sensor_temp_sensor_temp_changed();
  end_setup_batch_operator_interface_operator_interface_desired_temp();
  end_setup_batch_thermostat_thermostat_heat_control();
}

/// Complete pre-state for `thermostat_thermostat`: every input port and GUMBO state
/// variable it has.  There is deliberately no `Default` -- name every field.  An
/// event input is an `Option`: `Some(v)` for exactly `v` pending, `None` for nothing.
pub struct thermostat_thermostat_PreState {
  pub current_temp: Isolette_Data_Model::Temp,
  pub temp_changed: Option<u8>,
  pub desired_temp: Option<Isolette_Data_Model::Set_Points>,
  pub sv_currentSetPoints: Isolette_Data_Model::Set_Points,
  pub sv_lastCmd: Isolette_Data_Model::On_Off,
}

/// Establish the whole pre-state of `thermostat_thermostat` in one call.  The thread picks
/// it up on its next dispatch, so the usual ordering applies: park immediately
/// before it with `api::run_to_thread`, set, then `api::sstep(1)`.
pub fn set_thermostat_thermostat(s: thermostat_thermostat_PreState) {
  put_temp_sensor_temp_sensor_current_temp(s.current_temp);
  match s.temp_changed {
    Some(v) => setup_some_thermostat_thermostat_temp_changed(v),
    None => setup_none_thermostat_thermostat_temp_changed(),
  }
  match s.desired_temp {
    Some(v) => setup_some_thermostat_thermostat_desired_temp(v),
    None => setup_none_thermostat_thermostat_desired_temp(),
  }
  put_thermostat_thermostat_sv_currentSetPoints(s.sv_currentSetPoints);
  put_thermostat_thermostat_sv_lastCmd(s.sv_lastCmd);
}

/// Complete pre-state for `heat_source_heat_source`: every input port and GUMBO state
/// variable it has.  There is deliberately no `Default` -- name every field.  An
/// event input is an `Option`: `Some(v)` for exactly `v` pending, `None` for nothing.
